/* 裸 socket HTTP POST，host/port 可配，body 原样发送，resp 收响应体
 * （跳过 HTTP 头，返回响应体长度）。 */

static int sb_http_post(const char *host, uint16_t port,
                        const char *path, const char *content_type,
                        const uint8_t *body, size_t body_len,
                        char *resp, size_t resp_size, int timeout_ms)
{
  struct sockaddr_in addr;
  struct timeval tv;
  struct hostent *hp;
  char head[512];
  int fd;
  int ret;
  int total = 0;
  bool header_done = false;

  if (host == NULL || host[0] == '\0')
    {
      return -ENOTCONN;
    }

  hp = gethostbyname(host);
  if (hp == NULL)
    {
      /* 允许 IP 直连：inet_addr 转换 */
      in_addr_t ip = inet_addr(host);

      if (ip == INADDR_NONE)
        {
          return -ENOENT;
        }

      addr.sin_addr.s_addr = ip;
    }
  else
    {
      memcpy(&addr.sin_addr, hp->h_addr, hp->h_length);
    }

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      return -errno;
    }

  tv.tv_sec  = timeout_ms / 1000;
  tv.tv_usec = (timeout_ms % 1000) * 1000;
  setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  addr.sin_family = AF_INET;
  addr.sin_port   = htons(port);

  ret = connect(fd, (FAR struct sockaddr *)&addr, sizeof(addr));
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  snprintf(head, sizeof(head),
           "POST %s HTTP/1.1\r\n"
           "Host: %s:%u\r\n"
           "Content-Type: %s\r\n"
           "Content-Length: %zu\r\n"
           "Connection: close\r\n"
           "\r\n",
           path, host, (unsigned)port, content_type, body_len);

  /* 发送头部 + body */
  ret = send(fd, head, strlen(head), 0);
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  {
    size_t sent = 0;

    while (sent < body_len)
      {
        ret = send(fd, body + sent, body_len - sent, 0);
        if (ret <= 0)
          {
            close(fd);
            return -EIO;
          }

        sent += (size_t)ret;
      }
  }

  /* 收响应：跳过 HTTP 头，body 收进 resp */
  total = 0;
  while (total < (int)resp_size - 1)
    {
      char tmp[256];
      int n = recv(fd, tmp, sizeof(tmp) - 1, 0);

      if (n <= 0)
        {
          break;
        }

      if (!header_done)
        {
          /* 在 tmp 里找 \r\n\r\n */
          char *p = strstr(tmp, "\r\n\r\n");
          int skip;

          if (p != NULL)
            {
              skip = (int)(p - tmp) + 4;
              header_done = true;
            }
          else
            {
              /* 头可能跨 recv，简化：丢弃这包（头很短，几乎总是同包） */
              continue;
            }

          n -= skip;
          memcpy(resp + total, tmp + skip, n);
          total += n;
        }
      else
        {
          if (total + n < (int)resp_size)
            {
              memcpy(resp + total, tmp, n);
              total += n;
            }
        }
    }

  resp[total] = '\0';
  close(fd);
  return total;
}

/* JSON 字段提取：在 resp 中找 "key":"value" 或 "key":value，value 返回
 * （字符串去引号、\uXXXX 不解码——中文 UTF-8 原样保留在 JSON 里）。
 * 简化版：只处理 "key":"..."（字符串值）与 "key":"..." 截取。 */

static int sb_json_get_string(const char *json, const char *key,
                              char *out, size_t out_size)
{
  char pat[64];
  const char *p;
  const char *v;

  snprintf(pat, sizeof(pat), "\"%s\"", key);
  p = strstr(json, pat);
  if (p == NULL)
    {
      return -ENOENT;
    }

  p += strlen(pat);
  while (*p == ' ' || *p == ':' || *p == '\t')
    {
      p++;
    }

  if (*p != '"')
    {
      return -EINVAL;
    }

  p++;
  v = p;
  while (*p != '\0' && *p != '"')
    {
      p++;
    }

  if (*p != '"' || (size_t)(p - v) >= out_size)
    {
      return -EINVAL;
    }

  memcpy(out, v, p - v);
  out[p - v] = '\0';
  return (int)(p - v);
}

/* base64 解码（返回字节数） */

static int sb_base64_decode(const char *in, uint8_t *out, size_t out_max)
{
  size_t len = strlen(in);
  size_t i;
  size_t o = 0;
  uint32_t buf = 0;
  int bits = 0;

  for (i = 0; i < len && o < out_max; i++)
    {
      int v = g_b64tab[(unsigned char)in[i]];

      if (v < 0)
        {
          continue;
        }

      buf = (buf << 6) | (uint32_t)v;
      bits += 6;

      if (bits >= 8)
        {
          bits -= 8;
          out[o++] = (uint8_t)((buf >> bits) & 0xff);
        }
    }

  return (int)o;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int server_bridge_set_server(const char *host, uint16_t port)
{
  if (host == NULL || host[0] == '\0' || strlen(host) >= sizeof(g_sb_host))
    {
      return -EINVAL;
    }

  strncpy(g_sb_host, host, sizeof(g_sb_host) - 1);
  g_sb_host[sizeof(g_sb_host) - 1] = '\0';
  g_sb_port = port;
  printf("[Bridge] server = %s:%u\n", g_sb_host, (unsigned)g_sb_port);
  return 0;
}

int server_bridge_session_begin(void)
{
  if (g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  g_session = (g_session + 1) & 0x7fffffff;
  g_seq = 0;
  return g_session;
}

int server_bridge_upload(const int16_t *pcm, size_t samples)
{
  char path[128];
  char resp[512];
  size_t bytes = samples * 2;
  int ret;

  if (g_session < 0 || g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  snprintf(path, sizeof(path), "/voice/upload?session=%d&seq=%d",
           g_session, g_seq);

  ret = sb_http_post(g_sb_host, g_sb_port, path,
                     "application/octet-stream",
                     (const uint8_t *)pcm, bytes,
                     resp, sizeof(resp), SB_TIMEOUT_MS);
  if (ret < 0)
    {
      return ret;
    }

  g_seq++;
  return ret;
}

int server_bridge_finalize(char *text_out, size_t text_size,
                           uint8_t *audio_out, size_t audio_size)
{
  char path[128];
  char resp[SB_RESP_MAX];
  char b64[SB_RESP_MAX];
  int ret;
  int b64_len;

  if (g_session < 0 || g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  snprintf(path, sizeof(path), "/voice/finalize?session=%d", g_session);

  ret = sb_http_post(g_sb_host, g_sb_port, path,
                     "application/octet-stream",
                     NULL, 0,
                     resp, sizeof(resp), SB_FINALIZE_TMO);
  if (ret < 0)
    {
      return ret;
    }

  /* 解析 text */
  if (sb_json_get_string(resp, "text", text_out, text_size) < 0)
    {
      text_out[0] = '\0';
    }

  /* 解析 audio_b64 */
  b64_len = sb_json_get_string(resp, "audio_b64", b64, sizeof(b64));
  if (b64_len > 0)
    {
      return sb_base64_decode(b64, audio_out, audio_size);
    }

  return 0;
}
