 * 与 ai_voice_record 同源逻辑（read_slot → 丢头尾 → 3:2 降采样 → 高通
 * → 滤波链），但每 ~100ms 把 16kHz mono PCM 块回调给 cb——不攒 WAV。
 *
 * 实现要点：
 *  - 独立 static 滤波状态（与 record 的函数内 static 互不干扰）；
 *  - 输出块 static（100ms=1600 采样=3200B，不占栈/堆大块）；
 *  - 能量 VAD：回调块峰值低于阈值持续 silent_blocks 块 → 提前结束
 *    （silent_blocks=0 禁用，纯固定时长）；
 *  - ⚠️ 不用 NSNet2 降噪：其流水线写回依赖连续缓冲，与分块回调冲突
 *    （NS 留待服务器侧或延迟线方案）。
 ****************************************************************************/

int ai_voice_stream_record(ai_voice_stream_cb_t cb, void *arg,
                           int max_seconds, int silent_blocks)
{
  /* 独立滤波状态（stream 专用，与 record 隔离） */
  static int32_t s_hp_y = 0;
  static int32_t s_hp_prev = 0;
  static int16_t s_dl_buf[11];
  static uint32_t s_dl_cnt = 0;
  static int32_t s_lp_y = 0;

  /* 输出块：100ms @16kHz = 1600 采样 = 3200B（static，零分配） */
  static int16_t s_out[1600];

  FAR int16_t *chunk48;
  uint32_t chunk_samples;
  uint32_t out_n = 0;
  uint32_t want_out;
  uint32_t n16 = 0;
  uint32_t got = 0;
  bool first_chunk = true;
  int silent_cnt = 0;
  int ret;

  if (cb == NULL)
    {
      return -EINVAL;
    }

  if (max_seconds <= 0 || max_seconds > AI_VOICE_MAX_SECONDS)
    {
      max_seconds = AI_VOICE_MAX_SECONDS;
    }

  ret = ai_voice_init();
  if (ret < 0)
    {
      return ret;
    }

  chunk_samples = 1000;   /* 24kHz 2000B/读，同 record */
  chunk48 = (FAR int16_t *)malloc(chunk_samples * 2);
  if (chunk48 == NULL)
    {
      return -ENOMEM;
    }

  want_out = AI_VOICE_AI_RATE * (uint32_t)max_seconds;

  while (n16 < want_out)
    {
      uint32_t n_raw;
      uint32_t mi;
      uint32_t j;
      uint32_t n3;

      if (first_chunk)
        {
          first_chunk = false;
          continue;
        }

      ret = hal_i2s_read_slot(chunk48, chunk_samples * 2, 0);
      if (ret <= 0)
        {
          break;
        }

      n_raw = (uint32_t)ret / 2;

      /* 丢头尾瞬态（同 record：开 RX_SETTLE、末 RX_TAIL） */
      {
        uint32_t remain_out = want_out - n16;
        uint32_t use_end = n_raw - RX_TAIL_SAMPLES;

        if (use_end > RX_SETTLE_SAMPLES)
          {
            mi = use_end - RX_SETTLE_SAMPLES;
          }
        else
          {
            mi = 0;
          }

        if (mi > remain_out * 3 / 2)
          {
            mi = remain_out * 3 / 2;
          }
      }

      /* 24k → 16k 线性插值（同 record） */
      n3 = mi * 2 / 3;
      for (j = 0; j < n3; j++)
        {
          uint32_t pos2 = j * 3;
          uint32_t p0 = pos2 / 2;
          uint32_t frac = pos2 & 1;
          int32_t s0 = chunk48[RX_SETTLE_SAMPLES + p0];
          int32_t s1 = chunk48[RX_SETTLE_SAMPLES + p0 + 1];

          s_out[out_n + j] = (int16_t)((s0 * (2 - (int32_t)frac) +
                                        s1 * (int32_t)frac) / 2);
        }

      /* 滤波链（高通 → 11点中值 → 低通 → 软门，同 record PLANT_NO_NS 分支） */
      for (j = 0; j < n3; j++)
        {
          int32_t s = s_out[out_n + j];
          int a;
          int b;
          int16_t w[11];

          /* 高通：α=1/16（~220Hz 去 DC） */
          s_hp_y += s - s_hp_prev;
          s_hp_y -= s_hp_y >> 4;
          s = s_hp_y;
          s_hp_prev = s;

          /* 11 点延迟线 */
          for (a = 0; a < 10; a++)
            {
              s_dl_buf[a] = s_dl_buf[a + 1];
            }

          s_dl_buf[10] = (int16_t)s;
          s_dl_cnt++;

          if (s_dl_cnt >= 11)
            {
              int32_t m;

              /* 11 点排序取中值 */
              for (a = 0; a < 11; a++)
                {
                  w[a] = s_dl_buf[a];
                }

              for (a = 0; a < 10; a++)
                {
                  for (b = a + 1; b < 11; b++)
                    {
                      if (w[b] < w[a])
                        {
                          int16_t t = w[a];
                          w[a] = w[b];
                          w[b] = t;
                        }
                    }
                }

              m = w[5];

              /* 低通 5kHz（一阶 IIR，α=0.86） */
              s_lp_y += ((m - s_lp_y) * 86) / 100;
              m = s_lp_y;

              /* 限幅 ±30000 */
              if (m > 30000)
                {
                  m = 30000;
                }
              else if (m < -30000)
                {
                  m = -30000;
                }

              /* 软噪声门（|s|<500 衰减 1/4，500-1000 渐变，>1000 全通） */
              if (m > -1000 && m < 1000)
                {
                  int32_t ma = (m < 0) ? -m : m;

                  if (ma < 500)
                    {
                      m = m / 4;
                    }
                  else
                    {
                      m = m * 3 / 4;
                    }
                }

              s_out[out_n + j - 10] = (int16_t)m;
            }
          else
            {
              s_out[out_n + j] = (int16_t)s;
            }
        }

      out_n += n3;
      n16 += n3;
      got += mi;

      /* 输出块满（~100ms=1600 采样）→ 回调 */
      if (out_n >= 1600)
        {
          int32_t peak = 0;
          uint32_t k;
          int32_t amp = 0;

          for (k = 0; k < out_n; k++)
            {
              int32_t sv = s_out[k];

              if (sv < 0)
                {
                  sv = -sv;
                }

              if (sv > amp)
                {
                  amp = sv;
                }
            }

          peak = amp;

          /* 能量 VAD：块峰值 < 阈值 → 静音计数；说话 → 清零 */
          if (silent_blocks > 0 && peak < 800)
            {
              silent_cnt++;
            }
          else
            {
              silent_cnt = 0;
            }

          cb(s_out, out_n, arg);
          out_n = 0;

          if (silent_blocks > 0 && silent_cnt >= silent_blocks)
            {
              break;   /* 静音足够久 → 说完自动停 */
            }
        }
    }

  free(chunk48);

  /* 尾部不足一块的数据也回调（不丢尾） */
  if (out_n > 0 && cb != NULL)
    {
      cb(s_out, out_n, arg);
    }

  return (int)(n16 * 1000 / AI_VOICE_AI_RATE);   /* 录音时长 ms */
