static int sb_http_get_to_file(const char *host, uint16_t port,
                               const char *path,
                               const char *filepath, int timeout_ms)
{
  struct sockaddr_in addr;
  struct timeval tv;
  struct hostent *hp;
  char req[256];
  uint8_t buf[4096];
  FILE *fp;
  int fd;
  int ret;
  int written = 0;
  bool header_done = false;

  if (host == NULL || host[0] == '\0')
    {
      return -ENOTCONN;
    }

  hp = gethostbyname(host);
  if (hp == NULL)
    {
      in_addr_t ip = inet_addr(host);

      if (ip == INADDR_NONE)
        {
          return -ENOENT;
        }

      addr.sin_addr.s_addr = ip;
    }
  else
    {
      memcpy(&addr.sin_addr, hp->h_addr, hp->h_length);
    }

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      return -errno;
    }

  tv.tv_sec  = timeout_ms / 1000;
  tv.tv_usec = (timeout_ms % 1000) * 1000;
  setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  addr.sin_family = AF_INET;
  addr.sin_port   = htons(port);

  ret = connect(fd, (FAR struct sockaddr *)&addr, sizeof(addr));
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  snprintf(req, sizeof(req),
           "GET %s HTTP/1.1\r\n"
           "Host: %s:%u\r\n"
           "Connection: close\r\n"
           "\r\n",
           path, host, (unsigned)port);

  ret = send(fd, req, strlen(req), 0);
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  fp = fopen(filepath, "wb");
  if (fp == NULL)
    {
      close(fd);
      return -errno;
    }

  for (;;)
    {
      int n = recv(fd, buf, sizeof(buf), 0);

      if (n <= 0)
        {
          break;
        }

      if (!header_done)
        {
          char *p = strstr((char *)buf, "\r\n\r\n");
          int skip;

          if (p != NULL)
            {
              skip = (int)(p - (char *)buf) + 4;
              header_done = true;
            }
          else
            {
              continue;
            }

          n -= skip;
          if (n > 0)
            {
              fwrite(buf + skip, 1, n, fp);
              written += n;
            }
        }
      else
        {
          fwrite(buf, 1, n, fp);
          written += n;
        }
    }

  fclose(fp);
  close(fd);
  return written;
