  for (;;)
    {
      uint8_t ch[8];

      if (fread(ch, 1, 8, fp) != 8)
        {
          fclose(fp);
          return -EINVAL;
        }

      {
        uint32_t csize = (uint32_t)ch[4] | ((uint32_t)ch[5] << 8) |
                         ((uint32_t)ch[6] << 16) | ((uint32_t)ch[7] << 24);

        if (memcmp(ch, "data", 4) == 0)
          {
