/* 本地规则回复（接入 MiMo 全模态时替换）
 * 用真实传感器数据生成拟人化回答，离线可用。 */

static void local_reply(const char *question, char *out, size_t out_size)
{
  struct sensor_view_s view;

  (void)question;

  sensor_service_get_view(&view);

  if (view.valid)
    {
      /* 按水分状态生成回复 */

      if (view.moisture < 20.0f)
        {
          snprintf(out, out_size,
                   "土壤水分只有%.0f%%，我好渴呀！"
                   "快给我浇点水吧 💧",
                   view.moisture);
        }
      else if (view.moisture < 40.0f)
        {
          snprintf(out, out_size,
                   "土壤水分%.0f%%，有点干了呢。"
                   "今天可以浇一点水哦 🌱",
                   view.moisture);
        }
      else if (view.moisture <= 75.0f)
        {
          snprintf(out, out_size,
                   "土壤水分%.0f%%，还很滋润呢！"
                   "温度%.0f°C也很舒服，3天后再浇就好啦~ 😊",
                   view.moisture, view.temp);
        }
      else
        {
          snprintf(out, out_size,
                   "土壤水分%.0f%%，水有点多了，"
                   "先别浇啦，让土壤透透气~",
                   view.moisture);
        }
    }
  else
    {
      snprintf(out, out_size,
               "我还不知道土壤的情况呢，"
               "等我连上传感器再告诉你吧 🌱");
    }
}

