/****************************************************************************
 * 3C-2 图像识别：上传 RGB565 帧 → 服务器转 JPEG → MiMo 诊断 → 文本
 *
 * 协议：POST /image/analyze   body = RGB565 160×120 原始帧（38400B）
 *       响应 JSON {ok:true, text:"..."}
 * 与语音同架构：设备无 TLS 直连 MiMo，走局域网服务器中转。
 ****************************************************************************/

int server_bridge_image_analyze(const uint8_t *frame, size_t frame_len,
                                char *text_out, size_t text_size)
{
  char path[32];
  static char resp[SB_RESP_MAX];   /* static: 8KB worker 栈放不下 4096 */
  int ret;

  if (g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  snprintf(path, sizeof(path), "/image/analyze");

  ret = sb_http_post(g_sb_host, g_sb_port, path,
                     "application/octet-stream",
                     frame, frame_len,
                     resp, sizeof(resp), SB_FINALIZE_TMO);
  if (ret < 0)
    {
      printf("[Bridge] image analyze HTTP failed: %d\n", ret);
      return ret;
    }

  if (sb_json_get_string(resp, "text", text_out, text_size) < 0)
    {
      printf("[Bridge] image analyze: no text in response "
             "(%d bytes)\n", ret);
      text_out[0] = '\0';
      return -EINVAL;
    }

  return 0;
