/****************************************************************************
 * 顶栏实时时间（2026-08-31 用户要求）：GET /time → 服务器回北京时间
 *
 * 背景：ESP32-S3 无 RTC 电池，掉电时间丢 → 上电向局域网服务器要时间。
 * 服务器返回 {unix, date:"2026-08-31", time:"18:05"}，设备零解析负担。
 * 复用 sb_http_post 的 socket 逻辑，但 GET 无 body、响应是 JSON 小文本。
 ****************************************************************************/

int server_bridge_get_time(char *date_out, size_t date_size,
                           char *time_out, size_t time_size)
{
  static char resp[256];   /* /time 响应 <256B，static 防栈溢出 */
  int ret;

  if (g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  /* GET 请求：sb_http_post 是 POST，这里直接复用其 socket 流程。
   * 简化：构造 POST（无 body）→ 服务器 do_POST /time 也行；但统一
   * 用 GET 更语义化——直接调 sb_http_post 传空 body 会走 do_POST，
   * 服务器 do_POST 无 /time 分支 → 404。所以这里用 GET。
   * 实现：临时构造 GET 头 + 收响应（与 sb_http_get_to_file 同逻辑，
   * 但响应收进内存而非文件）。 */

  {
    struct sockaddr_in addr;
    struct timeval tv;
    struct hostent *hp;
    char req[128];
    char head[512];
    int fd;
    int total = 0;
    bool header_done = false;

    if (host_or_ip(g_sb_host, &addr, &hp) < 0)
      {
        return -ENOENT;
      }

    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0)
      {
        return -errno;
      }

    tv.tv_sec  = SB_TIMEOUT_MS / 1000;
    tv.tv_usec = (SB_TIMEOUT_MS % 1000) * 1000;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

    addr.sin_family = AF_INET;
    addr.sin_port   = htons(g_sb_port);

    if (connect(fd, (FAR struct sockaddr *)&addr, sizeof(addr)) < 0)
      {
        close(fd);
        return -errno;
      }

    snprintf(req, sizeof(req), "GET /time HTTP/1.1\r\n"
             "Host: %s:%u\r\nConnection: close\r\n\r\n",
             g_sb_host, (unsigned)g_sb_port);

    if (send(fd, req, strlen(req), 0) < 0)
      {
        close(fd);
        return -errno;
      }

    /* 收响应：跳过 HTTP 头，body 收进 resp */
    while (total < (int)sizeof(resp) - 1)
      {
        int n = recv(fd, head, sizeof(head) - 1, 0);

        if (n <= 0)
          {
            break;
          }

        head[n] = '\0';

        if (!header_done)
          {
            char *p = strstr(head, "\r\n\r\n");

            if (p != NULL)
              {
                int skip = (int)(p - head) + 4;

                header_done = true;
                n -= skip;
                if (n > 0)
                  {
                    strncpy(resp + total, head + skip, n);
                    total += n;
                  }
              }
          }
        else
          {
            strncpy(resp + total, head, n);
            total += n;
          }
      }

    resp[total] = '\0';
    close(fd);
  }

  if (sb_json_get_string(resp, "date", date_out, date_size) < 0 ||
      sb_json_get_string(resp, "time", time_out, time_size) < 0)
    {
      printf("[Bridge] /time 解析失败: %s\n", resp);
      return -EINVAL;
    }

  return 0;
