/****************************************************************************
 * 顶栏实时时间（2026-08-31 用户要求）：GET /time → 服务器回北京时间
 *
 * 背景：ESP32-S3 无 RTC 电池，掉电时间丢 → 上电向局域网服务器要时间。
 * 服务器 do_GET /time 返回 {unix, date:"2026-08-31", time:"18:05"}，
 * 设备零解析负担。socket 流程照抄 sb_http_post（已验证模式），
 * 但发 GET、响应收进内存（<256B）。
 ****************************************************************************/

int server_bridge_get_time(char *date_out, size_t date_size,
                           char *time_out, size_t time_size)
{
  static char resp[256];   /* /time 响应 <256B，static 防栈溢出 */
  struct sockaddr_in addr;
  struct timeval tv;
  struct hostent *hp;
  char req[128];
  char head[256];
  int fd;
  int ret;
  int total = 0;
  bool header_done = false;

  if (g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  hp = gethostbyname(g_sb_host);
  if (hp == NULL)
    {
      in_addr_t ip = inet_addr(g_sb_host);

      if (ip == INADDR_NONE)
        {
          return -ENOENT;
        }

      addr.sin_addr.s_addr = ip;
    }
  else
    {
      memcpy(&addr.sin_addr, hp->h_addr, hp->h_length);
    }

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      return -errno;
    }

  tv.tv_sec  = SB_TIMEOUT_MS / 1000;
  tv.tv_usec = (SB_TIMEOUT_MS % 1000) * 1000;
  setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  addr.sin_family = AF_INET;
  addr.sin_port   = htons(g_sb_port);

  ret = connect(fd, (FAR struct sockaddr *)&addr, sizeof(addr));
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  snprintf(req, sizeof(req),
           "GET /time HTTP/1.1\r\n"
           "Host: %s:%u\r\n"
           "Connection: close\r\n"
           "\r\n",
           g_sb_host, (unsigned)g_sb_port);

  ret = send(fd, req, strlen(req), 0);
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  /* 收响应：跳过 HTTP 头，body 收进 resp */

  while (total < (int)sizeof(resp) - 1)
    {
      int n = recv(fd, head, sizeof(head) - 1, 0);

      if (n <= 0)
        {
          break;
        }

      head[n] = '\0';

      if (!header_done)
        {
          char *p = strstr(head, "\r\n\r\n");

          if (p != NULL)
            {
              int skip = (int)(p - head) + 4;

              header_done = true;
              n -= skip;
              if (n > 0)
                {
                  memcpy(resp + total, head + skip, n);
                  total += n;
                }
            }
        }
      else
        {
          memcpy(resp + total, head, n);
          total += n;
        }
    }

  resp[total] = '\0';
  close(fd);

  if (sb_json_get_string(resp, "date", date_out, date_size) < 0 ||
      sb_json_get_string(resp, "time", time_out, time_size) < 0)
    {
      printf("[Bridge] /time 解析失败: %s\n", resp);
      return -EINVAL;
    }

  return 0;
}

int server_bridge_session_begin(void)"}

